{
  "name": "Match Results Management System",
  "description": "A comprehensive responsive web application for match coordinators, referees, and spectators to manage and view tournament results in real-time."
}

export enum MatchStatus {
  OPEN = 'OPEN',
  CLOSED = 'CLOSED'
}

export enum GameResult {
  PENDING = '待定',
  WIN = '勝',
  LOSS = '負',
  DRAW = '和'
}

export enum UserRole {
  GUEST = 'GUEST',
  ADMIN = 'ADMIN',
  REFEREE = 'REFEREE'
}

export interface PlayerInfo {
  id: string;
  name: string;
}

export interface TableMatch {
  tableNumber: number;
  player1: PlayerInfo;
  player2: PlayerInfo;
  assignedReferee: string;
  result: GameResult;
  submittedBy?: string;
  updatedAt?: string;
}

export interface MatchSession {
  id: string;
  title: string;
  status: MatchStatus;
  tables: TableMatch[];
  createdAt: string;
}

import { MatchSession } from '../types';

const STORAGE_KEY = 'match_results_app_data';

export const storageService = {
  getSessions: (): MatchSession[] => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },
  saveSessions: (sessions: MatchSession[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  },
  addSession: (session: MatchSession) => {
    const sessions = storageService.getSessions();
    sessions.push(session);
    storageService.saveSessions(sessions);
  },
  updateSession: (updatedSession: MatchSession) => {
    const sessions = storageService.getSessions();
    const index = sessions.findIndex(s => s.id === updatedSession.id);
    if (index !== -1) {
      sessions[index] = updatedSession;
      storageService.saveSessions(sessions);
    }
  }
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { UserRole, MatchSession } from './types';
import { storageService } from './services/storage';
import AdminPanel from './components/AdminPanel';
import RefereePanel from './components/RefereePanel';
import ResultsBoard from './components/ResultsBoard';
import LoginModal from './components/LoginModal';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [activeTab, setActiveTab] = useState<'admin' | 'referee' | 'results'>('results');
  const [showLogin, setShowLogin] = useState<UserRole | null>(null);
  const [sessions, setSessions] = useState<MatchSession[]>([]);

  useEffect(() => {
    setSessions(storageService.getSessions());
  }, []);

  const handleLogin = (targetRole: UserRole) => {
    setShowLogin(targetRole);
  };

  const onLoginSuccess = (successRole: UserRole) => {
    setRole(successRole);
    setShowLogin(null);
    setActiveTab(successRole === UserRole.ADMIN ? 'admin' : 'referee');
  };

  const updateSessions = () => {
    setSessions(storageService.getSessions());
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-indigo-700 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <i className="fas fa-trophy text-2xl text-yellow-400"></i>
            <h1 className="text-xl font-bold tracking-tight">比賽紀錄系統</h1>
          </div>

          <div className="hidden md:flex space-x-4">
            <button 
              onClick={() => setActiveTab('results')}
              className={`px-3 py-2 rounded-md text-sm font-medium transition ${activeTab === 'results' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
            >
              比賽結果
            </button>
            <button 
              onClick={() => handleLogin(UserRole.REFEREE)}
              className={`px-3 py-2 rounded-md text-sm font-medium transition ${activeTab === 'referee' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
            >
              裁判專區
            </button>
            <button 
              onClick={() => handleLogin(UserRole.ADMIN)}
              className={`px-3 py-2 rounded-md text-sm font-medium transition ${activeTab === 'admin' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
            >
              後台管理
            </button>
          </div>

          <div className="md:hidden">
             {/* Small screen role indicator */}
             <span className="text-xs bg-indigo-800 px-2 py-1 rounded-full border border-indigo-400">
               {role === UserRole.ADMIN ? '管理員' : role === UserRole.REFEREE ? '裁判' : '訪客'}
             </span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8">
        {activeTab === 'results' && (
          <ResultsBoard 
            sessions={sessions} 
            userRole={role} 
            onRefresh={updateSessions} 
          />
        )}

        {activeTab === 'admin' && role === UserRole.ADMIN && (
          <AdminPanel onSessionCreated={updateSessions} />
        )}

        {activeTab === 'referee' && role === UserRole.REFEREE && (
          <RefereePanel sessions={sessions} onResultSubmitted={updateSessions} />
        )}

        {(activeTab === 'admin' || activeTab === 'referee') && role === UserRole.GUEST && (
          <div className="text-center py-20">
            <i className="fas fa-lock text-5xl text-gray-300 mb-4"></i>
            <h2 className="text-2xl font-semibold text-gray-700">請先登入以使用此功能</h2>
            <div className="mt-6 space-x-4">
               <button 
                onClick={() => handleLogin(UserRole.ADMIN)}
                className="bg-indigo-600 text-white px-6 py-2 rounded-lg hover:bg-indigo-700 transition"
               >
                 後台登入
               </button>
               <button 
                onClick={() => handleLogin(UserRole.REFEREE)}
                className="bg-emerald-600 text-white px-6 py-2 rounded-lg hover:bg-emerald-700 transition"
               >
                 裁判登入
               </button>
            </div>
          </div>
        )}
      </main>

      {/* Mobile Footer Nav */}
      <nav className="md:hidden bg-white border-t border-gray-200 sticky bottom-0 z-50">
        <div className="flex justify-around">
          <button 
            onClick={() => setActiveTab('results')}
            className={`flex flex-col items-center py-3 px-4 ${activeTab === 'results' ? 'text-indigo-600' : 'text-gray-500'}`}
          >
            <i className="fas fa-list-ul"></i>
            <span className="text-[10px] mt-1">結果</span>
          </button>
          <button 
            onClick={() => handleLogin(UserRole.REFEREE)}
            className={`flex flex-col items-center py-3 px-4 ${activeTab === 'referee' ? 'text-indigo-600' : 'text-gray-500'}`}
          >
            <i className="fas fa-whistle"></i>
            <span className="text-[10px] mt-1">裁判</span>
          </button>
          <button 
            onClick={() => handleLogin(UserRole.ADMIN)}
            className={`flex flex-col items-center py-3 px-4 ${activeTab === 'admin' ? 'text-indigo-600' : 'text-gray-500'}`}
          >
            <i className="fas fa-user-shield"></i>
            <span className="text-[10px] mt-1">後台</span>
          </button>
        </div>
      </nav>

      {showLogin && (
        <LoginModal 
          targetRole={showLogin} 
          onClose={() => setShowLogin(null)} 
          onSuccess={onLoginSuccess} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface LoginModalProps {
  targetRole: UserRole;
  onClose: () => void;
  onSuccess: (role: UserRole) => void;
}

const LoginModal: React.FC<LoginModalProps> = ({ targetRole, onClose, onSuccess }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const correctPassword = targetRole === UserRole.ADMIN ? '0122' : '0987';
  const roleName = targetRole === UserRole.ADMIN ? '後台人員' : '裁判人員';

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === correctPassword) {
      onSuccess(targetRole);
    } else {
      setError('密碼錯誤，請重新輸入');
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black bg-opacity-50 p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-300">
        <div className="bg-indigo-600 p-6 text-white text-center">
          <i className={`fas ${targetRole === UserRole.ADMIN ? 'fa-user-shield' : 'fa-whistle'} text-4xl mb-4`}></i>
          <h2 className="text-2xl font-bold">{roleName} 登入</h2>
        </div>
        <form onSubmit={handleSubmit} className="p-8">
          <div className="mb-6">
            <label className="block text-gray-700 text-sm font-bold mb-2">請輸入密碼</label>
            <input
              autoFocus
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none transition text-center text-2xl tracking-widest"
              placeholder="••••"
            />
          </div>
          {error && <p className="text-red-500 text-sm mb-4 text-center font-medium">{error}</p>}
          <div className="flex space-x-3">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition font-medium"
            >
              取消
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition font-medium shadow-md"
            >
              確定登入
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default LoginModal;

import React, { useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types';
import { storageService } from '../services/storage';

interface AdminPanelProps {
  onSessionCreated: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSessionCreated }) => {
  const [title, setTitle] = useState('');
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, assignedReferee: '', result: GameResult.PENDING }
  ]);

  const addTable = () => {
    setTables([...tables, { 
      tableNumber: tables.length + 1, 
      player1: { id: '', name: '' }, 
      player2: { id: '', name: '' }, 
      assignedReferee: '', 
      result: GameResult.PENDING 
    }]);
  };

  const updateTable = (index: number, field: string, value: any) => {
    const newTables = [...tables];
    const target = { ...newTables[index] };

    if (field === 'p1Id') target.player1 = { ...target.player1!, id: value };
    else if (field === 'p1Name') target.player1 = { ...target.player1!, name: value };
    else if (field === 'p2Id') target.player2 = { ...target.player2!, id: value };
    else if (field === 'p2Name') target.player2 = { ...target.player2!, name: value };
    else if (field === 'tableNumber') target.tableNumber = parseInt(value) || 0;
    else if (field === 'referee') target.assignedReferee = value;

    newTables[index] = target;
    setTables(newTables);
  };

  const removeTable = (index: number) => {
    setTables(tables.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入場次標題');

    const newSession: MatchSession = {
      id: uuidv4(),
      title,
      status: MatchStatus.OPEN,
      createdAt: new Date().toISOString(),
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        assignedReferee: t.assignedReferee || '',
        result: GameResult.PENDING
      } as TableMatch))
    };

    storageService.addSession(newSession);
    setTitle('');
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, assignedReferee: '', result: GameResult.PENDING }]);
    onSessionCreated();
    alert('比賽場次已成功創建！');
  };

  return (
    <div className="space-y-8 max-w-4xl mx-auto">
      <div className="bg-white rounded-xl shadow-md p-6 border border-gray-100">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center">
          <i className="fas fa-plus-circle text-indigo-500 mr-2"></i>
          創建新比賽場次
        </h2>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">場次名稱 / 標題</label>
            <input 
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
              placeholder="例如：2024 春季業餘大賽 - 第一輪"
            />
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center border-b pb-2">
              <h3 className="text-lg font-medium text-gray-700">對弈對象配置</h3>
              <button 
                type="button"
                onClick={addTable}
                className="text-indigo-600 hover:text-indigo-800 text-sm font-semibold flex items-center"
              >
                <i className="fas fa-plus mr-1"></i> 新增桌號
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full min-w-[600px]">
                <thead>
                  <tr className="text-left text-xs text-gray-500 uppercase tracking-wider">
                    <th className="py-2 px-1">桌號</th>
                    <th className="py-2 px-1">先手(ID/姓名)</th>
                    <th className="py-2 px-1">後手(ID/姓名)</th>
                    <th className="py-2 px-1">裁判人員</th>
                    <th className="py-2 px-1">操作</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {tables.map((table, idx) => (
                    <tr key={idx} className="hover:bg-gray-50 transition">
                      <td className="py-2 px-1">
                        <input 
                          type="number" 
                          value={table.tableNumber}
                          onChange={(e) => updateTable(idx, 'tableNumber', e.target.value)}
                          className="w-16 px-2 py-1 border rounded"
                        />
                      </td>
                      <td className="py-2 px-1 space-y-1">
                        <input 
                          type="text" 
                          placeholder="ID"
                          value={table.player1?.id}
                          onChange={(e) => updateTable(idx, 'p1Id', e.target.value)}
                          className="w-24 px-2 py-1 border rounded text-xs block"
                        />
                        <input 
                          type="text" 
                          placeholder="姓名"
                          value={table.player1?.name}
                          onChange={(e) => updateTable(idx, 'p1Name', e.target.value)}
                          className="w-24 px-2 py-1 border rounded text-xs block"
                        />
                      </td>
                      <td className="py-2 px-1 space-y-1">
                        <input 
                          type="text" 
                          placeholder="ID"
                          value={table.player2?.id}
                          onChange={(e) => updateTable(idx, 'p2Id', e.target.value)}
                          className="w-24 px-2 py-1 border rounded text-xs block"
                        />
                        <input 
                          type="text" 
                          placeholder="姓名"
                          value={table.player2?.name}
                          onChange={(e) => updateTable(idx, 'p2Name', e.target.value)}
                          className="w-24 px-2 py-1 border rounded text-xs block"
                        />
                      </td>
                      <td className="py-2 px-1">
                        <input 
                          type="text" 
                          value={table.assignedReferee}
                          onChange={(e) => updateTable(idx, 'referee', e.target.value)}
                          className="w-24 px-2 py-1 border rounded text-xs"
                        />
                      </td>
                      <td className="py-2 px-1">
                        <button 
                          type="button"
                          onClick={() => removeTable(idx)}
                          className="text-red-500 hover:text-red-700"
                        >
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 transition shadow-lg active:transform active:scale-95"
          >
            確認創建比賽場次
          </button>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types';
import { storageService } from '../services/storage';

interface RefereePanelProps {
  sessions: MatchSession[];
  onResultSubmitted: () => void;
}

const RefereePanel: React.FC<RefereePanelProps> = ({ sessions, onResultSubmitted }) => {
  const [refereeName, setRefereeName] = useState('');
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [selectedTableNumber, setSelectedTableNumber] = useState<number | ''>('');
  const [result, setResult] = useState<GameResult>(GameResult.PENDING);

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const currentTable = currentSession?.tables.find(t => t.tableNumber === selectedTableNumber);

  // Clear table selection when session changes
  useEffect(() => {
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  }, [selectedSessionId]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!refereeName) return alert('請先輸入或選擇您的姓名');
    if (!currentSession) return alert('請選擇比賽場次');
    if (currentSession.status !== MatchStatus.OPEN) return alert('此場次已截止，無法傳送資料');
    if (selectedTableNumber === '') return alert('請選擇桌號');
    if (result === GameResult.PENDING) return alert('請選擇比賽結果');

    const updatedTables = currentSession.tables.map(t => {
      if (t.tableNumber === selectedTableNumber) {
        return {
          ...t,
          result,
          submittedBy: refereeName,
          updatedAt: new Date().toISOString()
        };
      }
      return t;
    });

    storageService.updateSession({
      ...currentSession,
      tables: updatedTables
    });

    onResultSubmitted();
    alert('結果已成功傳送！');
    // Reset selections for next table
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  };

  return (
    <div className="max-w-xl mx-auto space-y-6">
      <div className="bg-white rounded-xl shadow-md p-6 border border-emerald-100">
        <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center">
          <i className="fas fa-clipboard-check text-emerald-500 mr-2"></i>
          裁判結果回報
        </h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Step 0: Referee Name */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">您的姓名</label>
            <div className="relative">
              <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-gray-400">
                <i className="fas fa-user-tag"></i>
              </span>
              <input 
                type="text" 
                value={refereeName}
                onChange={(e) => setRefereeName(e.target.value)}
                className="w-full pl-10 pr-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition"
                placeholder="輸入您的姓名"
              />
            </div>
          </div>

          {/* Step 1: Select Session */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">選擇比賽場次</label>
            <select 
              value={selectedSessionId}
              onChange={(e) => setSelectedSessionId(e.target.value)}
              className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition bg-white"
            >
              <option value="">-- 請選擇場次 --</option>
              {sessions.map(s => (
                <option key={s.id} value={s.id}>
                  {s.title} {s.status === MatchStatus.CLOSED ? '(已截止)' : ''}
                </option>
              ))}
            </select>
          </div>

          {/* Step 2: Select Table */}
          {selectedSessionId && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">選擇桌號</label>
              <select 
                value={selectedTableNumber}
                onChange={(e) => setSelectedTableNumber(parseInt(e.target.value))}
                className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition bg-white"
              >
                <option value="">-- 請選擇桌號 --</option>
                {currentSession?.tables.map(t => (
                  <option key={t.tableNumber} value={t.tableNumber}>
                    第 {t.tableNumber} 桌 ({t.player1.name} vs {t.player2.name})
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* Auto Display Player 1 Info as requested */}
          {currentTable && (
            <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-100 animate-in fade-in duration-300">
              <p className="text-xs text-emerald-600 font-bold uppercase tracking-wider mb-2">對弈資訊</p>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-gray-500">先手選手 (P1)</p>
                  <p className="font-bold text-gray-800">{currentTable.player1.id} - {currentTable.player1.name}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">後手選手 (P2)</p>
                  <p className="font-bold text-gray-800">{currentTable.player2.id} - {currentTable.player2.name}</p>
                </div>
              </div>
            </div>
          )}

          {/* Step 3: Result Select */}
          {currentTable && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-3">比賽結果 (先手狀態)</label>
              <div className="grid grid-cols-3 gap-3">
                {[GameResult.WIN, GameResult.LOSS, GameResult.DRAW].map(res => (
                  <button
                    key={res}
                    type="button"
                    onClick={() => setResult(res)}
                    className={`py-3 rounded-lg font-bold border-2 transition ${
                      result === res 
                        ? 'bg-emerald-600 text-white border-emerald-600 shadow-md scale-105' 
                        : 'bg-white text-gray-600 border-gray-200 hover:border-emerald-200'
                    }`}
                  >
                    {res}
                  </button>
                ))}
              </div>
            </div>
          )}

          <button 
            type="submit"
            disabled={!currentTable || currentSession?.status === MatchStatus.CLOSED}
            className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition active:transform active:scale-95 flex items-center justify-center space-x-2 ${
              currentSession?.status === MatchStatus.CLOSED 
                ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                : 'bg-emerald-600 text-white hover:bg-emerald-700'
            }`}
          >
            <i className="fas fa-paper-plane"></i>
            <span>正式傳送結果</span>
          </button>

          {currentSession?.status === MatchStatus.CLOSED && (
            <p className="text-center text-red-500 text-sm font-medium">該比賽場次已截止接收資料</p>
          )}
        </form>
      </div>
    </div>
  );
};

