import { MatchSession } from '../types.ts';

const STORAGE_KEY = 'match_results_app_data';
const CLOUD_API_BASE = 'https://api.npoint.io/bins';

export const storageService = {
  getSessions: (): MatchSession[] => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveSessions: (sessions: MatchSession[]) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  },

  addSession: (session: MatchSession) => {
    const sessions = storageService.getSessions();
    sessions.push(session);
    storageService.saveSessions(sessions);
  },

  updateSession: (updatedSession: MatchSession) => {
    const sessions = storageService.getSessions();
    const index = sessions.findIndex(s => s.id === updatedSession.id);
    if (index !== -1) {
      sessions[index] = updatedSession;
      storageService.saveSessions(sessions);
    }
  },

  deleteSession: (id: string) => {
    const sessions = storageService.getSessions();
    const filtered = sessions.filter(s => s.id !== id);
    storageService.saveSessions(filtered);
  },

  // 雲端同步核心邏輯
  cloud: {
    // 創建一個新的雲端同步 Bin
    createBin: async (sessions: MatchSession[]) => {
      try {
        const response = await fetch(CLOUD_API_BASE, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessions, lastUpdate: new Date().toISOString() })
        });
        const result = await response.json();
        return result.binId; // 回傳給使用者的同步代碼
      } catch (error) {
        console.error('Failed to create cloud bin:', error);
        return null;
      }
    },

    // 更新現有的雲端資料
    updateBin: async (binId: string, sessions: MatchSession[]) => {
      try {
        await fetch(`${CLOUD_API_BASE}/${binId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ sessions, lastUpdate: new Date().toISOString() })
        });
        return true;
      } catch (error) {
        console.error('Failed to update cloud bin:', error);
        return false;
      }
    },

    // 抓取雲端資料
    fetchBin: async (binId: string) => {
      try {
        const response = await fetch(`${CLOUD_API_BASE}/${binId}`);
        if (!response.ok) throw new Error('Bin not found');
        const result = await response.json();
        return result.sessions as MatchSession[];
      } catch (error) {
        console.error('Failed to fetch cloud bin:', error);
        return null;
      }
    }
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserRole, MatchSession } from './types.ts';
import { storageService } from './services/storage.ts';
import AdminPanel from './components/AdminPanel.tsx';
import RefereePanel from './components/RefereePanel.tsx';
import ResultsBoard from './components/ResultsBoard.tsx';
import LoginModal from './components/LoginModal.tsx';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [activeTab, setActiveTab] = useState<'admin' | 'referee' | 'results'>('results');
  const [showLogin, setShowLogin] = useState<UserRole | null>(null);
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const [lastUpdate, setLastUpdate] = useState<Date>(new Date());
  const [syncId, setSyncId] = useState<string | null>(localStorage.getItem('current_sync_id'));
  const [isCloudSyncing, setIsCloudSyncing] = useState(false);

  const updateSessions = useCallback(() => {
    const data = storageService.getSessions();
    setSessions(data);
    setLastUpdate(new Date());
  }, []);

  // 處理雲端同步
  const handleCloudSync = useCallback(async () => {
    if (!syncId) return;
    setIsCloudSyncing(true);
    const cloudData = await storageService.cloud.fetchBin(syncId);
    if (cloudData) {
      // 簡單的合併策略：若雲端有資料，直接以雲端為準（覆蓋本地）
      storageService.saveSessions(cloudData);
      setSessions(cloudData);
      setLastUpdate(new Date());
    }
    setIsCloudSyncing(false);
  }, [syncId]);

  useEffect(() => {
    updateSessions();

    // 解析 URL 中的 syncId (例如 ?sid=123)
    const params = new URLSearchParams(window.location.search);
    const sid = params.get('sid');
    if (sid && sid !== syncId) {
      setSyncId(sid);
      localStorage.setItem('current_sync_id', sid);
    }

    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'match_results_app_data' || e.key === null) {
        updateSessions();
      }
    };
    window.addEventListener('storage', handleStorageChange);

    // 輪詢邏輯：如果有同步 ID，每 3 秒檢查雲端；否則檢查本地
    const interval = setInterval(() => {
      if (syncId) {
        handleCloudSync();
      } else {
        updateSessions();
      }
    }, 3500);

    return () => {
      window.removeEventListener('storage', handleStorageChange);
      clearInterval(interval);
    };
  }, [updateSessions, syncId, handleCloudSync]);

  const onSessionCreated = () => {
    updateSessions();
    // 若有同步 ID，創建後自動推送到雲端
    if (syncId) {
      storageService.cloud.updateBin(syncId, storageService.getSessions());
    }
  };

  const handleJoinSync = (id: string) => {
    setSyncId(id);
    localStorage.setItem('current_sync_id', id);
    alert(`已成功切換至同步 ID: ${id}`);
    handleCloudSync();
  };

  const stopSync = () => {
    if (window.confirm('確定停止同步？停止後將僅能看到本地儲存的舊資料。')) {
      setSyncId(null);
      localStorage.removeItem('current_sync_id');
    }
  };

  const onLoginSuccess = (successRole: UserRole) => {
    setRole(successRole);
    setShowLogin(null);
    setActiveTab(successRole === UserRole.ADMIN ? 'admin' : 'referee');
    updateSessions();
  };

  const getRoleLabel = (r: UserRole) => {
    switch (r) {
      case UserRole.ADMIN: return '後台人員';
      case UserRole.REFEREE: return '裁判人員';
      default: return '一般選手/訪客';
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-indigo-700 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setActiveTab('results')}>
            <i className="fas fa-trophy text-2xl text-yellow-400"></i>
            <h1 className="text-xl font-bold tracking-tight hidden sm:block">比賽紀錄系統</h1>
          </div>

          <div className="flex items-center space-x-1 sm:space-x-4">
            <nav className="flex space-x-1">
              <button onClick={() => setActiveTab('results')} className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'results' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}>比賽看板</button>
              <button onClick={() => { if(role === UserRole.REFEREE) setActiveTab('referee'); else setShowLogin(UserRole.REFEREE); }} className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'referee' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}>裁判專區</button>
              <button onClick={() => { if(role === UserRole.ADMIN) setActiveTab('admin'); else setShowLogin(UserRole.ADMIN); }} className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'admin' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}>後台管理</button>
            </nav>

            <div className="flex items-center ml-2 space-x-2">
               {syncId ? (
                 <div className="flex items-center bg-indigo-800 px-2 py-1 rounded border border-indigo-400" title={`同步 ID: ${syncId}`}>
                    <i className={`fas fa-cloud text-[10px] mr-1 ${isCloudSyncing ? 'animate-pulse text-green-400' : 'text-indigo-300'}`}></i>
                    <span className="text-[10px] font-mono font-bold">{syncId.substring(0,6)}</span>
                    <button onClick={stopSync} className="ml-1 text-[10px] text-indigo-400 hover:text-white"><i className="fas fa-times"></i></button>
                 </div>
               ) : (
                 <div className="hidden sm:flex items-center bg-slate-600 px-2 py-1 rounded text-[10px] text-slate-300">
                    <i className="fas fa-cloud-slash mr-1"></i> 本地模式
                 </div>
               )}
               {role !== UserRole.GUEST && (
                 <button onClick={() => {setRole(UserRole.GUEST); setActiveTab('results');}} className="bg-red-500 hover:bg-red-600 text-white w-8 h-8 rounded-full flex items-center justify-center transition shadow-sm"><i className="fas fa-sign-out-alt text-xs"></i></button>
               )}
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8">
        <div className="mb-4 flex justify-end items-center space-x-2">
            <span className="relative flex h-2 w-2">
              <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${syncId ? 'bg-green-400' : 'bg-blue-400'}`}></span>
              <span className={`relative inline-flex rounded-full h-2 w-2 ${syncId ? 'bg-green-500' : 'bg-blue-500'}`}></span>
            </span>
            <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
              {syncId ? `同步 ID: ${syncId}` : '本地資料'} (更新: {lastUpdate.toLocaleTimeString()})
            </span>
        </div>

        {activeTab === 'results' && (
          <ResultsBoard 
            sessions={sessions} 
            userRole={role} 
            onRefresh={syncId ? handleCloudSync : updateSessions} 
            onJoinSync={handleJoinSync}
            currentSyncId={syncId || undefined}
          />
        )}

        {activeTab === 'admin' && role === UserRole.ADMIN && (
          <AdminPanel onSessionCreated={onSessionCreated} currentSyncId={syncId || undefined} setSyncId={handleJoinSync} />
        )}

        {activeTab === 'referee' && role === UserRole.REFEREE && (
          <RefereePanel sessions={sessions} onResultSubmitted={onSessionCreated} />
        )}

        {showLogin && <LoginModal targetRole={showLogin} onClose={() => setShowLogin(null)} onSuccess={onLoginSuccess} />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  onSessionCreated: () => void;
  currentSyncId?: string;
  setSyncId: (id: string) => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSessionCreated, currentSyncId, setSyncId }) => {
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [isPublishing, setIsPublishing] = useState(false);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSessions();
  }, []);

  const loadSessions = () => {
    setSessions(storageService.getSessions());
  };

  const handleStartCloudSync = async () => {
    if (sessions.length === 0) return alert('請先建立至少一個比賽場次再發布');
    setIsPublishing(true);
    const binId = await storageService.cloud.createBin(sessions);
    if (binId) {
      setSyncId(binId);
      alert(`雲端同步已開啟！\n同步代碼為: ${binId}\n請將此代碼分享給裁判與選手。`);
    } else {
      alert('發布失敗，請稍後再試');
    }
    setIsPublishing(false);
  };

  const copyShareLink = () => {
    if (!currentSyncId) return;
    const url = `${window.location.origin}${window.location.pathname}?sid=${currentSyncId}`;
    navigator.clipboard.writeText(url);
    alert('分享連結已複製！發送此連結給他人可直接進入同步模式。');
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    setReferees(prev => [...new Set([...prev, ...names])]);
    setRefereeInput('');
  };

  const removeReferee = (name: string) => setReferees(referees.filter(r => r !== name));

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { tableNumber: nextNum, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const updateTable = (index: number, field: string, value: any) => {
    const newTables = [...tables];
    const target = { ...newTables[index] };
    if (field === 'p1Id') target.player1 = { ...target.player1!, id: value };
    else if (field === 'p1Name') target.player1 = { ...target.player1!, name: value };
    else if (field === 'p2Id') target.player2 = { ...target.player2!, id: value };
    else if (field === 'p2Name') target.player2 = { ...target.player2!, name: value };
    else if (field === 'tableNumber') target.tableNumber = parseInt(value) || 0;
    newTables[index] = target;
    setTables(newTables);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || referees.length === 0) return alert('請完整輸入標題與裁判');

    const sessionData = {
      title, referees,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) storageService.updateSession({ ...existing, ...sessionData });
    } else {
      storageService.addSession({ id: uuidv4(), status: MatchStatus.OPEN, createdAt: new Date().toISOString(), ...sessionData });
    }

    resetForm();
    onSessionCreated();
    loadSessions();
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('確定刪除？')) {
      storageService.deleteSession(id);
      loadSessions();
      onSessionCreated();
    }
  };

  return (
    <div className="space-y-8 max-w-5xl mx-auto pb-20">
      {/* 雲端同步區 */}
      <section className="bg-indigo-50 border-2 border-indigo-200 rounded-2xl p-6 shadow-sm">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div>
            <h2 className="text-xl font-black text-indigo-900 flex items-center">
              <i className="fas fa-cloud-upload-alt mr-2"></i>
              跨裝置同步設定
            </h2>
            <p className="text-sm text-indigo-700 mt-1">開啟雲端同步後，其他使用者只需輸入代碼即可即時觀看您的資料。</p>
          </div>
          {currentSyncId ? (
            <div className="flex items-center space-x-3">
              <div className="bg-white px-4 py-2 rounded-xl border-2 border-indigo-300 font-mono font-black text-indigo-600 text-lg">
                ID: {currentSyncId}
              </div>
              <button onClick={copyShareLink} className="bg-indigo-600 text-white px-4 py-2 rounded-xl font-bold hover:bg-indigo-700 transition">
                <i className="fas fa-share-alt mr-2"></i>複製連結
              </button>
            </div>
          ) : (
            <button 
              onClick={handleStartCloudSync} 
              disabled={isPublishing}
              className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-black hover:bg-indigo-700 transition shadow-lg disabled:opacity-50"
            >
              {isPublishing ? '發布中...' : '開啟雲端即時同步'}
            </button>
          )}
        </div>
      </section>

      {/* 場次列表 */}
      <section className="bg-white rounded-2xl shadow-sm border overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800">現有場次</h2>
          <span className="text-xs font-bold text-slate-400">若有變更，雲端將自動更新</span>
        </div>
        <div className="divide-y">
          {sessions.map(s => (
            <div key={s.id} className="p-4 flex justify-between items-center">
              <div>
                <h3 className="font-bold text-slate-800">{s.title}</h3>
                <p className="text-[10px] text-gray-400">桌數: {s.tables.length} | 裁判: {s.referees.length}</p>
              </div>
              <div className="flex space-x-2">
                <button onClick={() => {setEditingSessionId(s.id); setTitle(s.title); setReferees(s.referees); setTables(s.tables);}} className="text-indigo-600 p-2"><i className="fas fa-edit"></i></button>
                <button onClick={() => handleDelete(s.id)} className="text-red-500 p-2"><i className="fas fa-trash"></i></button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* 表單 */}
      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border">
        <h2 className="text-2xl font-black text-slate-800 mb-6">{editingSessionId ? '修改場次' : '建立場次'}</h2>
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-600">標題</label>
              <input type="text" value={title} onChange={e=>setTitle(e.target.value)} className="w-full p-3 border rounded-xl" placeholder="例：年度決賽" />
            </div>
            <div className="space-y-2">
              <label className="text-sm font-bold text-gray-600">裁判 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input type="text" value={refereeInput} onChange={e=>setRefereeInput(e.target.value)} className="flex-grow p-3 border rounded-xl" placeholder="輸入姓名" />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-4 rounded-xl">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {referees.map(r => (
                  <span key={r} className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold border flex items-center">
                    {r} <button onClick={()=>removeReferee(r)} className="ml-2 text-red-400"><i className="fas fa-times"></i></button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="pt-4 border-t">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold">桌次配置</h3>
              <button type="button" onClick={addTable} className="text-indigo-600 text-sm font-bold">+ 新增一桌</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-slate-50">
                  <tr><th className="p-2 text-left">桌號</th><th className="p-2 text-left">先手</th><th className="p-2 text-left">後手</th><th className="p-2 w-10"></th></tr>
                </thead>
                <tbody>
                  {tables.map((t, idx) => (
                    <tr key={idx} className="border-b">
                      <td className="p-2"><input type="number" value={t.tableNumber} onChange={e=>updateTable(idx,'tableNumber',e.target.value)} className="w-16 p-1 border rounded" /></td>
                      <td className="p-2 flex space-x-1">
                        <input type="text" placeholder="ID" value={t.player1?.id} onChange={e=>updateTable(idx,'p1Id',e.target.value)} className="w-12 p-1 border rounded text-xs" />
                        <input type="text" placeholder="姓名" value={t.player1?.name} onChange={e=>updateTable(idx,'p1Name',e.target.value)} className="w-full p-1 border rounded text-xs" />
                      </td>
                      <td className="p-2 flex space-x-1">
                        <input type="text" placeholder="ID" value={t.player2?.id} onChange={e=>updateTable(idx,'p2Id',e.target.value)} className="w-12 p-1 border rounded text-xs" />
                        <input type="text" placeholder="姓名" value={t.player2?.name} onChange={e=>updateTable(idx,'p2Name',e.target.value)} className="w-full p-1 border rounded text-xs" />
                      </td>
                      <td className="p-2 text-center"><button type="button" onClick={()=>setTables(tables.filter((_,i)=>i!==idx))} className="text-red-400"><i className="fas fa-trash"></i></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black text-lg shadow-lg">儲存場次</button>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { MatchSession, UserRole, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface ResultsBoardProps {
  sessions: MatchSession[];
  userRole: UserRole;
  onRefresh: () => void;
  onJoinSync?: (id: string) => void;
  currentSyncId?: string;
}

const ResultsBoard: React.FC<ResultsBoardProps> = ({ sessions, userRole, onRefresh, onJoinSync, currentSyncId }) => {
  const [selectedSessionId, setSelectedSessionId] = useState<string>('');
  const [editingTable, setEditingTable] = useState<{ sessionId: string, tableNumber: number } | null>(null);
  const [editResult, setEditResult] = useState<GameResult>(GameResult.PENDING);
  const [highlightedTables, setHighlightedTables] = useState<Set<number>>(new Set());
  const [inputSyncId, setInputSyncId] = useState('');

  const selectedSession = sessions.find(s => s.id === selectedSessionId);
  const isAuthorized = userRole === UserRole.ADMIN || userRole === UserRole.REFEREE;

  useEffect(() => {
    if (selectedSession) {
      const now = new Date().getTime();
      const recent = selectedSession.tables
        .filter(t => t.updatedAt && (now - new Date(t.updatedAt).getTime()) < 10000)
        .map(t => t.tableNumber);

      if (recent.length > 0) {
        setHighlightedTables(new Set(recent));
        const timer = setTimeout(() => setHighlightedTables(new Set()), 5000);
        return () => clearTimeout(timer);
      }
    }
  }, [selectedSession]);

  const toggleStatus = (session: MatchSession, newStatus: MatchStatus) => {
    if (userRole !== UserRole.ADMIN) return;
    storageService.updateSession({ ...session, status: newStatus });
    onRefresh();
  };

  const handleEdit = (table: TableMatch) => {
    setEditingTable({ sessionId: selectedSessionId, tableNumber: table.tableNumber });
    setEditResult(table.result);
  };

  const saveEdit = () => {
    if (!selectedSession || !editingTable) return;
    const updatedTables = selectedSession.tables.map(t => {
      if (t.tableNumber === editingTable.tableNumber) {
        return { 
          ...t, 
          result: editResult, 
          updatedAt: new Date().toISOString(), 
          submittedBy: `${userRole === UserRole.ADMIN ? '後台' : '裁判'}修改` 
        };
      }
      return t;
    });
    const updatedSession = { ...selectedSession, tables: updatedTables };
    storageService.updateSession(updatedSession);

    // 如果有雲端 ID，同步更新到雲端
    if (currentSyncId) {
      const allSessions = storageService.getSessions().map(s => s.id === updatedSession.id ? updatedSession : s);
      storageService.cloud.updateBin(currentSyncId, allSessions);
    }

    setEditingTable(null);
    onRefresh();
  };

  const handleSyncSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (inputSyncId.trim() && onJoinSync) {
      onJoinSync(inputSyncId.trim());
      setInputSyncId('');
    }
  };

